import torch
import torch.nn as nn
from torch.autograd import Function
from torch.utils.cpp_extension import load_inline

fused_ops_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_min_clamp_dropout_kernel(
    const float* input,
    const float* mask,
    float* output,
    float min_val,
    float max_val,
    float scale,
    int num_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        val = fminf(val, min_val);
        val = fmaxf(fminf(val, max_val), min_val);
        output[idx] = val * mask[idx] * scale;
    }
}

torch::Tensor fused_min_clamp_dropout_cuda(
    torch::Tensor input,
    torch::Tensor mask,
    float min_val,
    float max_val,
    float scale
) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;
    fused_min_clamp_dropout_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        mask.data_ptr<float>(),
        output.data_ptr<float>(),
        min_val,
        max_val,
        scale,
        num_elements
    );
    return output;
}
"""

cpp_wrapper = "torch::Tensor fused_min_clamp_dropout_cuda(torch::Tensor input, torch::Tensor mask, float min_val, float max_val, float scale);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=cpp_wrapper,
    cuda_sources=fused_ops_code,
    functions=['fused_min_clamp_dropout_cuda'],
    verbose=True
)

class FusedMinClampDropout(Function):
    @staticmethod
    def forward(ctx, input, min_val, max_val, dropout_p, training):
        ctx.min_val = min_val
        ctx.max_val = max_val
        ctx.dropout_p = dropout_p
        ctx.training = training

        if training and dropout_p > 0:
            mask = torch.bernoulli(torch.full_like(input, 1 - dropout_p))
            scale = 1.0 / (1 - dropout_p)
        else:
            mask = torch.ones_like(input)
            scale = 1.0

        output = fused_ops.fused_min_clamp_dropout_cuda(input, mask, min_val, max_val, scale)
        ctx.save_for_backward(mask)
        ctx.scale = scale
        return output

    @staticmethod
    def backward(ctx, grad_output):
        mask, = ctx.saved_tensors
        grad_input = grad_output * mask * ctx.scale
        return grad_input, None, None, None, None

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, groups, min_value, max_value, dropout_p):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.norm = nn.GroupNorm(groups, out_channels)
        self.min_value = min_value
        self.max_value = max_value
        self.dropout_p = dropout_p

    def forward(self, x):
        x = self.conv(x)
        x = self.norm(x)
        x = FusedMinClampDropout.apply(x, self.min_value, self.max_value, self.dropout_p, self.training)
        return x
